// Design tokens. GENERATED by tools\New-Theme.ps1 from design\tokens.json.
//
// Do not edit by hand: CI regenerates this and fails if it differs, so a change
// made here and not in the design system would be reverted anyway. Edit
// design\tokens.json instead, run the generator, and commit both.
//
// The style is Swiss International Typographic: a 12-column grid, flush-left
// ragged-right text, square corners everywhere, no blurred shadows, hierarchy
// from size and weight, and one accent -- iron-oxide red -- used once per view.
// Depth comes from flat colour planes overlapping on the grid, which is why
// Plane2 inverts between themes: the upper plane has to keep reading as the
// upper plane in both.

using System;
using System.Windows;
using System.Windows.Media;

namespace EULord.Ui
{
    /// <summary>Which palette the window is painted with.</summary>
    internal enum ThemeMode { Light, Dark }

    internal static class Theme
    {
        private static ThemeMode _mode = ThemeMode.Light;

        /// <summary>Raised after Mode changes, so open windows can repaint.</summary>
        public static event EventHandler Changed;

        public static ThemeMode Mode
        {
            get { return _mode; }
            set
            {
                if (_mode == value) return;
                _mode = value;
                EventHandler handler = Changed;
                if (handler != null) handler(null, EventArgs.Empty);
            }
        }

        public static bool IsDark { get { return _mode == ThemeMode.Dark; } }

        private static Brush Pick(uint light, uint dark)
        {
            return _mode == ThemeMode.Dark ? Frozen(dark) : Frozen(light);
        }

        private static readonly System.Collections.Generic.Dictionary<uint, Brush> _brushes =
            new System.Collections.Generic.Dictionary<uint, Brush>();

        /// <summary>One frozen brush per colour, so repainting allocates nothing.</summary>
        private static Brush Frozen(uint argb)
        {
            Brush brush;
            if (_brushes.TryGetValue(argb, out brush)) return brush;

            var solid = new SolidColorBrush(Color.FromArgb(
                (byte)((argb >> 24) & 0xFF), (byte)((argb >> 16) & 0xFF),
                (byte)((argb >> 8) & 0xFF), (byte)(argb & 0xFF)));
            solid.Freeze();
            _brushes[argb] = solid;
            return solid;
        }

        // -- colour ----------------------------------------------------------

        /// <summary>The window's own background, visible between the colour planes.</summary>
        public static Brush Ground { get { return Pick(0xFFD6D6D2u, 0xFF000000u); } }

        /// <summary>Text directly on ground: the title bar, the legend under the data bar.</summary>
        public static Brush GroundInk { get { return Pick(0xFF111111u, 0xFFEFEFEDu); } }

        /// <summary>Secondary text on ground. 7.3:1 light, 7.8:1 dark.</summary>
        public static Brush GroundMuted { get { return Pick(0xFF4F4F4Cu, 0xFFA3A39Fu); } }

        /// <summary>The lower colour plane: the status readout and every expander.</summary>
        public static Brush Plane1 { get { return Pick(0xFFFFFFFFu, 0xFF1C1C1Bu); } }

        /// <summary>Primary text on plane-1. 18.9:1 light, 13.4:1 dark.</summary>
        public static Brush Plane1Ink { get { return Pick(0xFF111111u, 0xFFEFEFEDu); } }

        /// <summary>Secondary text on plane-1. 6.6:1 light, 7.0:1 dark.</summary>
        public static Brush Plane1Muted { get { return Pick(0xFF5D5D5Au, 0xFFA3A39Fu); } }

        /// <summary>Hairline rules inside plane-1. Decorative: never the only edge of a control.</summary>
        public static Brush Plane1Hair { get { return Pick(0xFFDAD9D5u, 0xFF333331u); } }

        /// <summary>The upper colour plane, overlapping plane-1: the count and the apply button. Inverts between themes so the layering reads the same way in both.</summary>
        public static Brush Plane2 { get { return Pick(0xFF111111u, 0xFFECECE9u); } }

        /// <summary>Primary text on plane-2. 17.6:1 light, 17.0:1 dark.</summary>
        public static Brush Plane2Ink { get { return Pick(0xFFF3F3F1u, 0xFF111111u); } }

        /// <summary>Secondary text on plane-2. 7.6:1 light, 6.0:1 dark.</summary>
        public static Brush Plane2Muted { get { return Pick(0xFFA6A6A2u, 0xFF5D5D5Au); } }

        /// <summary>Hairline rules inside plane-2.</summary>
        public static Brush Plane2Hair { get { return Pick(0xFF2E2E2Du, 0xFFCFCFCBu); } }

        /// <summary>The one accent. Iron-oxide red, the same in both themes. Once per view.</summary>
        public static Brush Red { get { return Pick(0xFFB3402Eu, 0xFFB3402Eu); } }

        /// <summary>Hover and pressed fill of red surfaces, and the progress band over them.</summary>
        public static Brush RedDeep { get { return Pick(0xFF8E3122u, 0xFF7E2B1Eu); } }

        /// <summary>The accent as text on ground and plane-1. 5.1:1 light, 6.4:1 dark.</summary>
        public static Brush RedInk { get { return Pick(0xFFB3402Eu, 0xFFDD7664u); } }

        /// <summary>Text and icons on red and red-deep. 5.5:1.</summary>
        public static Brush OnRed { get { return Pick(0xFFFFFFFFu, 0xFFFFFFFFu); } }

        /// <summary>An unlit segment of the 68-policy data bar, and an empty progress track.</summary>
        public static Brush SegOff { get { return Pick(0xFFBDBDB8u, 0xFF2D2D2Bu); } }

        /// <summary>A lit segment: one of the 40 gains.</summary>
        public static Brush SegOn { get { return Pick(0xFF111111u, 0xFFEFEFEDu); } }

        /// <summary>The hatching over the 7 losses. Never carries meaning on its own.</summary>
        public static Brush Held { get { return Pick(0xFF5F5F5Bu, 0xFF8F8F8Bu); } }

        /// <summary>Hover wash on ground and plane-1. Alpha hex: 5% ink.</summary>
        public static Brush Hover1 { get { return Pick(0x0D111111u, 0x0DFFFFFFu); } }

        /// <summary>Hover wash on plane-2.</summary>
        public static Brush Hover2 { get { return Pick(0x12F3F3F1u, 0x0D111111u); } }

        /// <summary>The 2px keyboard focus ring, offset 2px. Plain ink, never the accent.</summary>
        public static Brush Focus { get { return Pick(0xFF111111u, 0xFFEFEFEDu); } }

        /// <summary>Fill behind the title bar's close button on hover.</summary>
        public static Brush CloseHover { get { return Pick(0xFFB3402Eu, 0xFFB3402Eu); } }

        /// <summary>The scroll thumb at rest. Alpha hex: 35% ink, so it reads on both the ground and a colour plane without a track behind it.</summary>
        public static Brush ScrollThumb { get { return Pick(0x59111111u, 0x59FFFFFFu); } }

        /// <summary>The scroll thumb while hovered or dragged. 65% ink.</summary>
        public static Brush ScrollThumbHover { get { return Pick(0xA6111111u, 0xA6FFFFFFu); } }

