        /// <summary>
        /// The one easing curve in the product: symmetric, mechanical, no overshoot.
        /// This is a tool reporting what it did, not an app being charming.
        /// </summary>
        public static System.Windows.Media.Animation.IEasingFunction Mech()
        {
            var ease = new System.Windows.Media.Animation.CubicEase
            {
                EasingMode = System.Windows.Media.Animation.EasingMode.EaseInOut
            };
            return ease;
        }

        /// <summary>True when the viewer asked Windows for less motion.</summary>
        public static bool ReduceMotion
        {
            get
            {
                try { return !SystemParameters.ClientAreaAnimation; }
                catch (Exception) { return false; }
            }
        }
